{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["header","directions-list"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Design proposals","title":"Choose a look for your deck","subtitle":"Each direction is a full theme, shown on a title slide drawn in it."},"children":[]}}
{"op":"add","path":"/elements/directions-list","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"repeat":{"statePath":"/result/directions"},"children":["direction-section"]}}
{"op":"add","path":"/elements/direction-section","value":{"type":"Section","props":{"title":{"$item":"theme/name"},"lede":{"$item":"theme/style/overall"}},"children":["direction-body"]}}
{"op":"add","path":"/elements/direction-body","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["slide-picture","palette-swatches","specs-split","exclusions-collapsible"]}}
{"op":"add","path":"/elements/slide-picture","value":{"type":"Picture","props":{"path":"mockup","alt":{"$template":"Title slide drawn in ${theme/name}"},"aspect":"auto"},"children":[]}}
{"op":"add","path":"/elements/palette-swatches","value":{"type":"Swatches","props":{"colors":[{"$item":"theme/colors/primary"},{"$item":"theme/colors/secondary"},{"$item":"theme/colors/accent"},{"$item":"theme/colors/background"},{"$item":"theme/colors/text_primary"},{"$item":"theme/colors/text_secondary"}]},"children":[]}}
{"op":"add","path":"/elements/specs-split","value":{"type":"Split","props":{"ratio":"1:1","gap":"lg"},"children":["type-stack","layout-stack"]}}
{"op":"add","path":"/elements/type-stack","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["type-heading","type-family","type-headings","type-body"]}}
{"op":"add","path":"/elements/type-heading","value":{"type":"Heading","props":{"text":"Type","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/type-family","value":{"type":"Detail","props":{"label":"Typeface","value":{"$item":"theme/typography/font_family"}},"children":[]}}
{"op":"add","path":"/elements/type-headings","value":{"type":"Detail","props":{"label":"Headings","value":{"$item":"theme/typography/heading_style"}},"children":[]}}
{"op":"add","path":"/elements/type-body","value":{"type":"Detail","props":{"label":"Body","value":{"$item":"theme/typography/body_style"}},"children":[]}}
{"op":"add","path":"/elements/layout-stack","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["layout-heading","layout-aspect","layout-margins","layout-alignment","style-icons","style-graphics"]}}
{"op":"add","path":"/elements/layout-heading","value":{"type":"Heading","props":{"text":"Layout & style","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/layout-aspect","value":{"type":"Detail","props":{"label":"Slide shape","value":{"$item":"theme/layout/aspect_ratio"}},"children":[]}}
{"op":"add","path":"/elements/layout-margins","value":{"type":"Detail","props":{"label":"Margins","value":{"$item":"theme/layout/margins"}},"children":[]}}
{"op":"add","path":"/elements/layout-alignment","value":{"type":"Detail","props":{"label":"Alignment","value":{"$item":"theme/layout/alignment"}},"children":[]}}
{"op":"add","path":"/elements/style-icons","value":{"type":"Detail","props":{"label":"Icons","value":{"$item":"theme/style/icon_style"}},"children":[]}}
{"op":"add","path":"/elements/style-graphics","value":{"type":"Detail","props":{"label":"Graphics","value":{"$item":"theme/style/graphic_style"}},"children":[]}}
{"op":"add","path":"/elements/exclusions-collapsible","value":{"type":"Collapsible","props":{"title":"What this look avoids","defaultOpen":false},"children":["exclusions-text"]}}
{"op":"add","path":"/elements/exclusions-text","value":{"type":"Text","props":{"text":{"$item":"theme/exclusions"},"variant":"body"},"children":[]}}
